local config = {
  ui_story_31190101_1_dialog_content = "Navigator, Navigator!",
  ui_story_31190101_2_dialog_content = "Vice? What's wrong?",
  ui_story_31190101_X2_dialog_content = "Something big is up!",
  ui_story_31190101_3_dialog_content = "A strange sign appeared along the hallway!",
  ui_story_31190101_4_dialog_content = "A sign? What kind of sign?",
  ui_story_31190101_5_dialog_content = "It's... It's a wooden sign.",
  ui_story_31190101_X5_dialog_content = "There's a huge Illumina symbol on one side.",
  ui_story_31190101_6_dialog_content = "And someone has carved the words <color=#FFB400>\"All ye brave enough to challenge the Colossus' mightiest, touch this sign, if you dare!\"</color> on the reverse side.",
  ui_story_31190101_7_dialog_content = "Does that mean... someone on the Colossus is looking for a fight?",
  ui_story_31190101_8_dialog_content = "I'm not sure...",
  ui_story_31190101_9_dialog_content = "But if experience is anything to go by, it looks like someone is making trouble again!",
  ui_story_31190101_11_dialog_content = "See? It's right here...",
  ui_story_31190101_12_dialog_content = "Yes... I see it.",
  ui_story_31190101_13_dialog_content = "Could this be some kind of challenge from someone on the Colossus?",
  ui_story_31190101_14_dialog_content = "This challenge... It feels like we might have some serious trouble on our hands!",
  ui_story_31190101_15_dialog_content = "If a fight breaks out on the Colossus, who knows how serious the damage will be!",
  ui_story_31190101_16_dialog_content = "And if they end up damaging the Colossus' facilities... Just thinking about the repair bills makes my head hurt!",
  ui_story_31190101_17_dialog_content = "Navigator, our savings are at stake here...",
  ui_story_31190101_18_dialog_content = "Vice, just try to calm down a little...",
  ui_story_31190101_19_dialog_content = "I'm trying! But really, who would do such a thing on the Colossus!?",
  ui_story_31190101_20_dialog_content = "Vice, nothing has happened yet. Don't get carried away...",
  ui_story_31190101_21_dialog_content = "Your tail is flailing around all over the place!",
  ui_story_31190101_22_dialog_content = "Hey... What was that sound?",
  ui_story_31190101_23_dialog_content = "Your tail... knocked the wooden sign down.",
  ui_story_31190101_24_dialog_content = "So, it was you... You dare to challenge the Colossus' mightiest—<color=#FFB400>Revy</color>?",
  ui_story_31190101_25_dialog_content = "Eeeek!",
  ui_story_31190101_26_dialog_content = "Yes, Vice—the long-tailed archer, have come here to challenge me, you do?",
  ui_story_31190101_27_dialog_content = "No, no, no...",
  ui_story_31190101_28_dialog_content = "Look, Revy! I don't want to challenge anyone! My tail accidentally knocked the sign down, see?",
  ui_story_31190101_29_dialog_content = "Wait... \"Challenge me\"? You mean, you're the one who put this sign here?",
  ui_story_31190101_30_dialog_content = "Of course, I did.",
  ui_story_31190101_31_dialog_content = "So, that means... Revy, are you, uh, the Colossus' mightiest?",
  ui_story_31190101_32_dialog_content = "You think so, too? Ah, but of course! Heroic minds think alike.",
  ui_story_31190101_33_dialog_content = "Ahaha... So, you're waiting here for someone to challenge you?",
  ui_story_31190101_34_dialog_content = "Aye, and you are the first one to touch that wooden sign.",
  ui_story_31190101_35_dialog_content = "Right... But Revy, you showed up the moment I touched it!",
  ui_story_31190101_36_dialog_content = "Yeah... How did you know it was Vice who touched it in the first place?",
  ui_story_31190101_37_dialog_content = "Is this some kind of new Illumina technology we don't know about?",
  ui_story_31190101_38_dialog_content = "Well, hiding just over there and lurking in the shadows, I was...",
  ui_story_31190101_39_dialog_content = "Lurking in the shadows? You mean, you've been secretly watching to see who would touch your sign...?",
  ui_story_31190101_40_dialog_content = "Correct... Was it that obvious?",
  ui_story_31190101_41_dialog_content = "And it was Vice who touched my wooden sign first.",
  ui_story_31190101_42_dialog_content = "So now, Vice must challenge me. Let this battle decide, once and for all—who is the mightiest!",
  ui_story_31190101_43_dialog_content = "But Revy... Umm... It was really only just a teeny tiny little accident...",
  ui_story_31190101_44_dialog_content = "But you still touched it.",
  ui_story_31190101_45_dialog_content = "Hmm... How about we just skip the challenge and agree that you're the mightiest?",
  ui_story_31190101_46_dialog_content = "That won't do! Only through mortal combat can I prove that I am worthy of the title \"The Colossus' Mightiest\"!",
  ui_story_31190101_47_dialog_content = "How did I get myself into this mess...!?",
  ui_story_31190101_48_dialog_content = "Are you ready to commence our fated duel?",
  ui_story_31190101_49_dialog_content = "Erm, Revy... How about you put down your weapon, and we try talking this out...?",
  ui_story_31190101_50_dialog_content = "Very well.",
  ui_story_31190101_51_dialog_content = "The thing is, all of us living on the Colossus are on the same side. There's no need to be going around challenging each other...",
  ui_story_31190101_52_dialog_content = "And what's more... we're both Illumina soldiers!",
  ui_story_31190101_53_dialog_content = "Soldiers must also hone their fighting skills amongst themselves.",
  ui_story_31190101_54_dialog_content = "And that goes doubly for soldiers on the front line! Steel ourselves in fresh blood and the raging flames of battle, we must!",
  ui_story_31190101_55_dialog_content = "Huh? You mean, you want to make me... bleed!?",
  ui_story_31190101_56_dialog_content = "I was thinking about it.",
  ui_story_31190101_57_dialog_content = "I think we should just save our strength for fighting the Eclipsites, together...",
  ui_story_31190101_58_dialog_content = "That would be a much better way of steeling ourselves than this competition of yours... What do you say?",
  ui_story_31190101_59_dialog_content = "Deny there is some truth in your words, I cannot, but I see no harm in promoting a little healthy competition.",
  ui_story_31190101_60_dialog_content = "You two, how about we take a break and talk about this later?",
  ui_story_31190101_61_dialog_content = "Break time! Break time!",
  ui_story_31190101_62_dialog_content = "Competition! Error! Error!",
  ui_story_31190101_63_dialog_content = "Competition, confirmed!",
  ui_story_31190101_64_dialog_content = "Incorrect! Error! Commencing repairs!",
  ui_story_31190101_65_dialog_content = "Repair mechanism error! Repair mechanism error!",
  ui_story_31190101_66_dialog_content = "Oh no... It's the Fireflies.",
  ui_story_31190101_67_dialog_content = "Now their recordings and system sounds are all jumbled up. What a racket...",
  ui_story_31190101_68_dialog_content = "Can you just stop!? You're giving me a headache!",
  ui_story_31190101_69_dialog_content = "Navigator! I'm not trying to cause anyone a headache... We were just engaging in a reasonable discussion. Allies should never fight!",
  ui_story_31190101_70_dialog_content = "You should know, detest arguing, I do...",
  ui_story_31190101_71_dialog_content = "And fighting? I said we should merely engage in friendly competition. Although, some might say there is no difference in the meaning of these two words.",
  ui_story_31190101_72_dialog_content = "There is no difference! Especially when you're talking about blood!",
  ui_story_31190101_73_dialog_content = "Hmm? Really? Perhaps... But that's not the point.",
  ui_story_31190101_74_dialog_content = "Hey, I wasn't talking about you two!",
  ui_story_31190101_75_dialog_content = "You two! You two!",
  ui_story_31190101_76_dialog_content = "(This is a nightmare... Things are spiraling out of control here...)",
  ui_story_31190101_77_dialog_content = "(That's it!)",
  ui_story_31190101_X77_dialog_content = "(I'm always passing out, right? I might use it to put an end to all this!)",
  ui_story_31190101_78_dialog_content = "Vice... Revy... Stop arguing...",
  ui_story_31190101_79_dialog_content = "I...",
  ui_story_31190101_80_dialog_content = "Oh, no! Navigator! Navigator! Have you passed out!?",
  ui_story_31190101_81_dialog_content = "Was my mighty presence too much for the weak Navigator?",
  ui_story_31190101_82_dialog_content = "<color=#e8d9bb>You are taken back to your room by Vice and Revy...</color>",
  ui_story_31190101_83_dialog_content = "<color=#e8d9bb>Several hours later...</color>",
  ui_story_31190101_84_dialog_content = "Wow... It actually worked.",
  ui_story_31190101_85_dialog_content = "And I prevented a fight from breaking out on the Colossus...",
  ui_story_31190101_86_dialog_content = "Huh? Who?",
  ui_story_31190101_87_dialog_content = "It's me. I see you're awake.",
  ui_story_31190101_88_dialog_content = "Oh... Come in.",
  ui_story_31190101_89_dialog_content = "Are you feeling better?",
  ui_story_31190101_90_dialog_content = "More or less.",
  ui_story_31190101_91_dialog_content = "So, the reason you fainted was that I wished to engage in a challenge and fight aboard the Colossus... right?",
  ui_story_31190101_92_option_content = "That's not the reason!",
  ui_story_31190101_93_dialog_content = "Really? But one mention of fighting and you went out like a light.",
  ui_story_31190101_94_option_content = "Correct.",
  ui_story_31190101_95_dialog_content = "Just as I suspected.",
  ui_story_31190101_96_dialog_content = "Well, I've removed the wooden sign.",
  ui_story_31190101_97_dialog_content = "As long as I don't stake another challenge, you won't faint again, will you?",
  ui_story_31190101_98_dialog_content = "Yes, you're right!",
  ui_story_31190101_99_dialog_content = "Hmm. I see.",
  ui_story_31190101_100_dialog_content = "Well then, I shall take my leave.",
  ui_story_31190101_101_dialog_content = "<color=#e8d9bb>A few days later.</color>",
  ui_story_31190101_102_dialog_content = "*Ringing*",
  ui_story_31190101_103_dialog_content = "Isn't it still the lunch break...? Did I just dream that an alarm was ringing...?",
  ui_story_31190101_104_dialog_content = "Firefly flashes...? That means...",
  ui_story_31190101_105_dialog_content = "This isn't a dream!",
  ui_story_31190101_106_dialog_content = "What's going on?",
  ui_story_31190101_107_dialog_content = "Lounge! Sandbag repair failure! Lounge! Sandbag repair failure!",
  ui_story_31190101_108_dialog_content = "Phew... From what I can see, Soroz is still in one piece...",
  ui_story_31190101_109_dialog_content = "I'd better go check on the Lounge.",
  ui_story_31190101_110_dialog_content = "<color=#e8d9bb>A loud noise comes from the Lounge.</color>",
  ui_story_31190101_111_dialog_content = "Now, the <color=#FFB400>Eclipsite Annihilation Assembly</color> enters its final interactive session.",
  ui_story_31190101_112_dialog_content = "You there—explain how you'd go about killing an Eclipsite, and demonstrate your method for us on those sandbags.",
  ui_story_31190101_113_dialog_content = "Just as I showed you.",
  ui_story_31190101_114_dialog_content = "Ha! I drove an armored truck over an Eclipsite once!",
  ui_story_31190101_X114_dialog_content = "Just like this!",
  ui_story_31190101_115_dialog_content = "Ever smelled Eclipsite juice? That stuff is not for the faint of heart!",
  ui_story_31190101_116_dialog_content = "Sandbag—bag exploded and sand overflowed... Attempting to repair! Attempting to repair!",
  ui_story_31190101_117_dialog_content = "I usually use my magic to kill those things.",
  ui_story_31190101_118_dialog_content = "They close their eyes and live no more. I believe it to be a very simple and direct method.",
  ui_story_31190101_X118_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_31190101_119_dialog_content = "Sandbag unbound! Attempting to repair! Attempting to repair!",
  ui_story_31190101_120_dialog_content = "Eclipsites? I just grab my gun and pull the trigger until it goes... \"click.\" Heh...",
  ui_story_31190101_121_dialog_content = "Sandbag—Sand leakage detected! Attempting to repair! Attempting to repair!",
  ui_story_31190101_122_dialog_content = "Back then, me and the boys threw ourselves into hordes of those things without taking so much as a scratch...",
  ui_story_31190101_123_dialog_content = "We attacked them so fast, those things stood there for a few seconds before realizing what was even going on! Then came the running... Tsk...",
  ui_story_31190101_124_dialog_content = "Sandbags repaired successfully! No ruptures located!",
  ui_story_31190101_X124_dialog_content = "Ha!",
  ui_story_31190101_125_dialog_content = "Sandbag—Sandbag destroyed! Failure! Repairs failed! Repairs failed!",
  ui_story_31190101_126_dialog_content = "I have made an official record of all your contributions. You have shared 265 different ways to kill Eclipsites.",
  ui_story_31190101_127_dialog_content = "You all look satisfied for now. Let us continue our collaboration next time.",
  ui_story_31190101_128_dialog_content = "And with that, I hereby declare this meeting over!",
  ui_story_31190101_129_dialog_content = "Luckily, it seems to be some kind of... discussion they're having...",
  ui_story_31190101_130_dialog_content = "<color=#e8d9bb>After returning to your room...</color>",
  ui_story_31190101_131_dialog_content = "Twenty sandbags broken.",
  ui_story_31190101_132_dialog_content = "<anim type=Shake><size=45>Twenty sandbags broken!!!</size></anim>",
  ui_story_31190101_133_dialog_content = "I know...",
  ui_story_31190101_134_dialog_content = "You should be glad that's all that was broken!",
  ui_story_31190101_135_dialog_content = "Forget about it. As long as they don't fight each other on the Colossus, I can take twenty broken sandbags any day.",
  ui_story_31190101_136_dialog_content = "<color=#e8d9bb>The next day.</color>",
  ui_story_31190101_137_dialog_content = "Umm... Are you there?",
  ui_story_31190101_138_dialog_content = "I'm here. What's up, Revy?",
  ui_story_31190101_139_dialog_content = "Your Fireflies repeatedly broadcasted... my exploits... throughout the Colossus yesterday.",
  ui_story_31190101_140_dialog_content = "Exploits?",
  ui_story_31190101_141_dialog_content = "The broken sandbags.",
  ui_story_31190101_142_dialog_content = "I apologize.",
  ui_story_31190101_143_dialog_content = "We destroyed twenty sandbags yesterday. If Vice hadn't eventually stopped us, even more would have met a similar fate.",
  ui_story_31190101_144_dialog_content = "That's not right. Such an apology doesn't seem formal enough. Before I came here, I specifically asked Vice how to apologize sincerely.",
  ui_story_31190101_145_dialog_content = "Ahem... I am truly sorry for the great loss I caused both you and the Colossus yesterday, Navigator, I am.",
  ui_story_31190101_146_dialog_content = "There's no need to be so formal...",
  ui_story_31190101_147_dialog_content = "It's really not a big deal. As long as you don't fight on the Colossus, anything else is fine by me.",
  ui_story_31190101_148_dialog_content = "Really?",
  ui_story_31190101_149_dialog_content = "When you say it's not a big deal, you mean you're not angry?",
  ui_story_31190101_150_option_content = "Of course.",
  ui_story_31190101_151_dialog_content = "You have not misunderstood my intentions, I see!",
  ui_story_31190101_152_option_content = "I'm a little mad, to be honest...",
  ui_story_31190101_153_dialog_content = "Then please, feel free to unleash your fury upon me.",
  ui_story_31190101_154_dialog_content = "We really did not intend to damage your Colossus. I just wanted to prove...",
  ui_story_31190101_155_dialog_content = "I know.",
  ui_story_31190101_156_dialog_content = "To prove that I am indeed the Colossus' mightiest...",
  ui_story_31190101_157_dialog_content = "Be that as it may, allies should never fight each other... especially on the Colossus!",
  ui_story_31190101_158_dialog_content = "Abide by this statement, I shall... most likely.",
  ui_story_31190101_159_dialog_content = "<color=#e8d9bb>A day later, as Soroz is about to land...</color>",
  ui_story_31190101_160_dialog_content = "Huh? There's something at the door.",
  ui_story_31190101_161_dialog_content = "Signed—Master of Alter-Blade, Mechanical Overlord, and the Colossus' Ultimate Vanguard—Revy.",
  ui_story_31190101_162_dialog_content = "Let's see what we've got here...",
  ui_story_31190101_163_dialog_content = "Yikes! What is that awful smell!?",
  ui_story_31190101_164_dialog_content = "There's a note inside...",
  ui_story_31190101_165_dialog_content = "\"Since I can neither challenge my allies nor fight on the Colossus...\"",
  ui_story_31190101_166_dialog_content = "\"Once we land, I shall challenge the leader of my allies—the Caelestite!\"",
  ui_story_31190101_167_dialog_content = "Urgh, I feel like this smell is going to make me pass out again...",
  ui_story_31190101_X167_dialog_content = "...",
  ui_story_31190101_168_dialog_content = "Actually, considering Revy's challenge, maybe passing out wouldn't be such a bad thing right now...",
  ui_story_31190601_1_dialog_content = "Thanks to you, we were able to identify the robber in no time.",
  ui_story_31190601_2_dialog_content = "Your help is much appreciated. Rest assured, he'll get the punishment he deserves...",
  ui_story_31190601_3_dialog_content = "I was just doing what I felt I should. I'm always happy to help!",
  ui_story_31190601_4_dialog_content = "<color=#e8d9bb>Thud, thud, thud!</color>",
  ui_story_31190601_5_dialog_content = "Huh? What was that noise?",
  ui_story_31190601_6_dialog_content = "It sounded like someone—no, like a couple of people just fell on the ground.",
  ui_story_31190601_7_dialog_content = "Ah, must be the new kid again. I swear, ever since she got here, it just never seems to stop...",
  ui_story_31190601_8_dialog_content = "The \"new kid\"? I don't think a kid could be making that kind of noise...",
  ui_story_31190601_9_dialog_content = "Heh, I wouldn't believe it either if I hadn't seen it for myself.",
  ui_story_31190601_10_dialog_content = "The day she arrived, I went to her cell to deliver her meal. At the time, everything looked perfectly normal.",
  ui_story_31190601_11_dialog_content = "But when I came back to pick up her tray, everyone else in the cell had been knocked out by that crazy brat.",
  ui_story_31190601_12_dialog_content = "And as they lay there unconscious all over the floor, she was sitting off to the side, eating their meals as though nothing had happened.",
  ui_story_31190601_13_dialog_content = "Sigh... We've relocated her 16 times by now. At this rate, the only place for her will be solitary confinement.",
  ui_story_31190601_14_dialog_content = "Wait, you're telling me... One little girl fought and won against all the convicts in 15 prison cells?!",
  ui_story_31190601_15_dialog_content = "(An insanely-powerful little girl who loves to fight... I have a bad feeling about this...)",
  ui_story_31190601_16_dialog_content = "That's right, which is why I should really go take a look at what's happened this time.",
  ui_story_31190601_17_dialog_content = "Sorry, but you'll have to see yourself out. You know where the exit is, right?",
  ui_story_31190601_18_dialog_content = "Er, if it isn't too much trouble... May I come with you?",
  ui_story_31190601_19_dialog_content = "With me?",
  ui_story_31190601_20_dialog_content = "P-Please don't get the wrong idea! I promise I'm not up to anything!",
  ui_story_31190601_21_dialog_content = "It's just that I have a feeling I might be able to help you with this.",
  ui_story_31190601_22_dialog_content = "Well... Knock yourself out, kid.",
  ui_story_31190601_23_dialog_content = "Especially since you've already helped us out a bunch and all. If anyone asks, I'll just say we took a quick detour on the way out.",
  ui_story_31190601_24_dialog_content = "But no funny business, got it? Otherwise, it's my head on the chopping block.",
  ui_story_31190601_25_dialog_content = "Got it!",
  ui_story_31190601_26_dialog_content = "Don't tell me there aren't any other cells left?",
  ui_story_31190601_27_dialog_content = "This was a bigger let-down than I thought... Could I have gotten that much stronger already?",
  ui_story_31190601_28_dialog_content = "(Wait, that sounds like...)",
  ui_story_31190601_29_dialog_content = "Revy?!",
  ui_story_31190601_30_dialog_content = "Huh? Oh, hey PlayerName! Did you get arrested, too?",
  ui_story_31190601_31_dialog_content = "You two know each other?",
  ui_story_31190601_32_dialog_content = "Yeah... Quite a bit, actually...",
  ui_story_31190601_33_dialog_content = "You know, I always took you as the goody-goody hero type, like the main character in a comic book. Never thought I'd see you in jail someday!",
  ui_story_31190601_34_dialog_content = "But since you're here... Guess I have no choice but to knock you out too.",
  ui_story_31190601_35_dialog_content = "I-I didn't get arrested at all! I just came to identify a suspect in a robbery.",
  ui_story_31190601_36_dialog_content = "Hold on a second. Did you beat up all these convicts here... by yourself?",
  ui_story_31190601_37_dialog_content = "That's right!",
  ui_story_31190601_38_dialog_content = "So the guard wasn't kidding... You seriously beat up every single prisoner in the entire jail on your own?!",
  ui_story_31190601_39_dialog_content = "Yeah, but these guys weren't as fun as the ones in the last fifteen cells. I hardly even touched them before they fell straight to the ground!",
  ui_story_31190601_40_dialog_content = "Unbelievable... Not a single person in this stinkin' Umbraton jail knows how to fight!",
  ui_story_31190601_41_dialog_content = "T-This facility is only meant to house petty criminals! But judging from the last two days, I don't think this is the right place for you either...",
  ui_story_31190601_42_dialog_content = "Huh? You're letting me go, then?",
  ui_story_31190601_43_dialog_content = "In your dreams! In just two days, you managed to beat the heck out of every single inmate in this place!",
  ui_story_31190601_44_dialog_content = "At first, I thought it was because you didn't get along with the prisoners in the first cell. But it turns out, you had a bone to pick with every person in the whole damn place!",
  ui_story_31190601_45_dialog_content = "If you don't come up with a better excuse for all this fighting, I'll have no choice but to transfer you to solitary confinement.",
  ui_story_31190601_46_dialog_content = "...",
  ui_story_31190601_47_dialog_content = "Last chance, kid—why'd you pick a fight with every one of your cellmates?",
  ui_story_31190601_48_dialog_content = "(She keeps glancing at me... Is there something she can't tell the guard?)",
  ui_story_31190601_49_dialog_content = "S-Sir? Could we have a moment to talk in private?",
  ui_story_31190601_50_dialog_content = "I only need ten minutes. Please trust me!",
  ui_story_31190601_51_dialog_content = "You can keep an eye on us from the other side of the cell. I promise I won't break any laws!",
  ui_story_31190601_52_dialog_content = "... Fine. I gotta call the prison doctor over here, anyway.",
  ui_story_31190601_53_dialog_content = "There are guards posted at the door as well, so don't even try to escape.",
  ui_story_31190601_54_dialog_content = "Thank you for your trust, sir.",
  ui_story_31190601_55_dialog_content = "The guard is long gone, Revy. I think you can speak freely now.",
  ui_story_31190601_56_dialog_content = "A-About what? I-I have no idea what you're talking about...",
  ui_story_31190601_57_dialog_content = "I'm talking about the reason you started a brawl in prison!",
  ui_story_31190601_58_dialog_content = "They'll lock you up all by yourself if you don't tell the truth!",
  ui_story_31190601_59_dialog_content = "... Fine, but I'm only telling you.",
  ui_story_31190601_60_dialog_content = "Since it matters so much to you... I was just <color=#FFB400>playing by prison rules</color>, that's all.",
  ui_story_31190601_61_dialog_content = "\"Prison rules\"...?",
  ui_story_31190601_62_dialog_content = "Yup!",
  ui_story_31190601_63_dialog_content = "See, there's no store in prison. You can't just buy whatever you want.",
  ui_story_31190601_64_dialog_content = "If you really want something in here, you take it from someone else... By force, if needed.",
  ui_story_31190601_65_dialog_content = "And that's prison rules, in a nutshell.",
  ui_story_31190601_66_dialog_content = "If that's the case, then why didn't you just tell the guard? I'm sure he's seen it all by now.",
  ui_story_31190601_67_dialog_content = "Now's not the right time to tell him. I'm still super frustrated and annoyed.",
  ui_story_31190601_68_dialog_content = "For what reason? Revy, you've sent everyone in here sprawling. Didn't you get what you wanted?",
  ui_story_31190601_69_dialog_content = "That's just it! I beat them all, every single one! That's what's so annoying.",
  ui_story_31190601_70_dialog_content = "But my target and my reason for going into jail in the first place hasn't even come yet! I still haven't gotten what I came for!",
  ui_story_31190601_71_dialog_content = "<size=45>You sent yourself to jail just so you could retrieve something?!</size>",
  ui_story_31190601_72_dialog_content = "What on earth is so important that you'd willingly go to prison for it?!",
  ui_story_31190601_73_dialog_content = "Well, since it's you, I guess I could tell you, PlayerName.",
  ui_story_31190601_74_dialog_content = "It's a legendary treasure, one that countless people have chased after. A treasure that has bested even the greatest of history's warriors!",
  ui_story_31190601_75_dialog_content = "Just one sniff will make anyone's scalp prickle and burn...",
  ui_story_31190601_76_dialog_content = "And just one taste will make your whole head turn all red and sweaty...",
  ui_story_31190601_77_dialog_content = "But even so, people can't resist its power and will continue scarfing it down like a bunch of crazed addicts...",
  ui_story_31190601_78_dialog_content = "W-Wait a minute!",
  ui_story_31190601_79_dialog_content = "What you're describing sounds way too dangerous...",
  ui_story_31190601_80_dialog_content = "Are you sure you know what you're doing?!",
  ui_story_31190601_81_dialog_content = "What're you saying? I'm talking about the <color=#FFB400>Super Blazing Hot Sauce</color>!",
  ui_story_31190601_82_dialog_content = "Huh? You were talking about hot sauce?",
  ui_story_31190601_83_dialog_content = "What else could it be? There's only one thing that matches my description, and that's Super Blazing Hot Sauce.",
  ui_story_31190601_84_dialog_content = "You see, \"spicy\" isn't just a flavor. It's a kind of pain.",
  ui_story_31190601_85_dialog_content = "Eating spicy foods makes your body constantly produce adrenaline and other endorphins, which in turn make you feel excitement and satisfaction.",
  ui_story_31190601_86_dialog_content = "With this stuff, you'll be able to keep moving forward even after your tongue goes totally numb!",
  ui_story_31190601_87_dialog_content = "Ah, the more I talk about it, the more I want to taste its shocking deliciousness... I want it so much!",
  ui_story_31190601_88_dialog_content = "So the reason you beat up all these prisoners... was just to get your hands on some special hot sauce?",
  ui_story_31190601_89_dialog_content = "First of all, it's called <color=#FFB400>Super Blazing Hot Sauce</color>.",
  ui_story_31190601_90_dialog_content = "Second, I just told you that countless people have only ever dreamed of having it! I'd do anything just to get my hands on some!",
  ui_story_31190601_91_dialog_content = "I mean, I believe you there... After all, you were even willing to go to jail for it. I wonder if Gram's ever heard of—",
  ui_story_31190601_92_dialog_content = "<size=45>Stop!!!</size>",
  ui_story_31190601_93_dialog_content = "He, uh... doesn't know that I'm here.",
  ui_story_31190601_94_dialog_content = "I was helping ol' Gram buy some ingredients in Umbraton when I overheard some folks talking about hot sauce.",
  ui_story_31190601_95_dialog_content = "I couldn't help myself, so I walked over to hear more. I never expected to hear them mention <color=#FFB400>Super Blazing Hot Sauce</color> though.",
  ui_story_31190601_96_dialog_content = "One of them said that it's served almost exclusively in prisons.",
  ui_story_31190601_97_dialog_content = "With its powerful flavor, a single drop is all you need for an entire bowl of food. Originally, it was specially designed as the ultimate prison meal seasoning.",
  ui_story_31190601_98_dialog_content = "As a result of its incredible flavor, it became a form of hard currency within the prison system.",
  ui_story_31190601_99_dialog_content = "With just a single bottle of <color=#FFB400>Super Blazing Hot Sauce</color>, a person could trade it for anything they could ever want in prison.",
  ui_story_31190601_100_dialog_content = "But even after beating the living daylights out of all these prisoners, I still haven't seen so much as a drop of the stuff...",
  ui_story_31190601_101_dialog_content = "It's been ten minutes! Your little \"visitation\" is over now.",
  ui_story_31190601_102_dialog_content = "You're just in time, sir!",
  ui_story_31190601_103_dialog_content = "I couldn't find what I wanted in here, so you can let me go now.",
  ui_story_31190601_104_dialog_content = "Well, given how small your crime was in the first place, I could've just let you go already...",
  ui_story_31190601_105_dialog_content = "But after seeing you beat up every single prisoner we have in this place, I'm afraid you'll have to stick around a while longer.",
  ui_story_31190601_106_dialog_content = "<size=45>What?! Are you kidding me?!</size>",
  ui_story_31190601_107_dialog_content = "Now that we're on the subject, what exactly did you do to get thrown in jail, Revy?",
  ui_story_31190601_108_dialog_content = "I didn't want to break the law or nothin'... I just wanted to get in here.",
  ui_story_31190601_109_dialog_content = "So I stood in front of a patrolman, pulled a traffic sign out of the ground, and then jammed it back in place a few times.",
  ui_story_31190601_110_dialog_content = "After that, they charged me with vandalism of public property and threw me in here.",
  ui_story_31190601_111_dialog_content = "I guess that explains a lot about the nature of the crimes of the convicts here...",
  ui_story_31190601_112_dialog_content = "I gotta transport all of these prisoners to the medical ward. Tonight, you gotta sit here all by yourself and think about what you've done.",
  ui_story_31190601_113_dialog_content = "W-Wait, sir. Just out of curiousity, have you ever heard of a certain... super-spicy hot sauce?",
  ui_story_31190601_114_dialog_content = "It's called <color=#FFB400>Super Blazing Hot Sauce</color>!",
  ui_story_31190601_115_dialog_content = "Y-Yeah, that. I hear it tastes amazing and that it's used as a kind of hard currency in jails.",
  ui_story_31190601_116_dialog_content = "What sauce, now? I've never heard of anything of the sort.",
  ui_story_31190601_117_dialog_content = "Besides, Umbraton jails use canned meat as their form of hard currency.",
  ui_story_31190601_118_dialog_content = "<size=45>What?!?</size>",
  ui_story_31190601_119_dialog_content = "But how could this be...? How could a prison not have my legendary hot sauce...?",
  ui_story_31190601_120_dialog_content = "... Are you okay, Revy?",
  ui_story_31190601_121_dialog_content = "You look like your soul has left you...",
  ui_story_31190601_122_dialog_content = "I... I'll be okay...",
  ui_story_31190601_123_dialog_content = "PlayerName... I could really go for some of Gram's home cooking right now...",
  ui_story_31190601_124_option_content = "Don't worry. I'll see what I can do to get you out!",
  ui_story_31190601_125_dialog_content = "Er, sir? You said that her crime was light enough to let her go already, right?",
  ui_story_31190601_126_dialog_content = "Also, her little scuffle with the other prisoners should be considered part of the unspoken \"prison rules\" here.",
  ui_story_31190601_127_dialog_content = "Is there any chance you could...",
  ui_story_31190601_128_dialog_content = "Nope. But I'll let you know right away once she's free to go.",
  ui_story_31190601_129_dialog_content = "I-I see... I'm sorry, Revy. It's out of my hands.",
  ui_story_31190601_130_option_content = "I'm sorry, I can't help you get out.",
  ui_story_31190601_131_dialog_content = "I mean, criminals or not, you did attack all these people...",
  ui_story_31190601_132_dialog_content = "B-But don't worry! I'll make sure to bring you some of Gram's food as soon as they let you out!",
  ui_story_31190601_133_dialog_content = "Sigh... I knew it. Guess you really can't count on anyone but yourself, huh?",
  ui_story_31190601_134_dialog_content = "Good thing I started preparing for this day years ago.",
  ui_story_31190601_135_dialog_content = "What kind of person prepares for being in jail one day?",
  ui_story_31190601_136_dialog_content = "That's not important. What's important is that I've spent the last five years preparing myself in case I found myself needing to bust myself out of prison.",
  ui_story_31190601_137_dialog_content = "Looks like it's finally time to put \"that\" move to good use...",
  ui_story_31190601_138_dialog_content = "<color=#e8d9bb>Thud, thud, thud...</color>",
  ui_story_31190601_139_dialog_content = "Uh, Revy? What're you doing in that corner over there?",
  ui_story_31190601_140_dialog_content = "That sounds an awful lot like... <size=45>A-Are you digging a tunnel?!</size>",
  ui_story_31190601_141_dialog_content = "Shhh!!! Keep it down, will you?!",
  ui_story_31190601_142_dialog_content = "I did the math. If I start digging right now, I should make it all the way back to Gannon City in just under ten years.",
  ui_story_31190601_143_dialog_content = "Once I finally dig my way to freedom, even the powers up above will be impressed!",
  ui_story_31190601_144_dialog_content = "And when that glorious day comes, I'll raise this blade that helped me escape, look up into the pouring rain, and shout to the heavens—",
  ui_story_31190601_145_dialog_content = "But the guard is still here, Revy. He's been watching you dig this whole time.",
  ui_story_31190601_146_dialog_content = "Eh?",
  ui_story_31190601_147_dialog_content = "Also... I'm pretty sure he heard everything you just said.",
  ui_story_31190601_148_dialog_content = "Dig away, for all I care.",
  ui_story_31190601_149_dialog_content = "There are plenty of prisoners here who want to dig their way out. You're not the first, and you most certainly won't be the last.",
  ui_story_31190601_150_dialog_content = "Most of them give up after about three days, though. The longest I've seen a prisoner keep going is a week, and even then... The \"tunnel\" they dug was just a meter-deep hole.",
  ui_story_31190601_151_dialog_content = "Wow... Did they give up because it was too difficult a task?",
  ui_story_31190601_152_dialog_content = "I mean, not really. Like I said, this place is only meant to hold petty criminals. We usually only hold them up to a week before we let them go.",
  ui_story_31190601_153_dialog_content = "So I'm stuck here for a whole week...?",
  ui_story_31190601_154_dialog_content = "That won't be necessary. I already requested a special release document from the Shadowlord. You can come with me now.",
  ui_story_31190601_155_dialog_content = "Allura! You came to save me!",
  ui_story_31190601_156_dialog_content = "Yes! I knew I wasn't meant to be cooped up in a place like this forever!",
  ui_story_31190601_157_dialog_content = "Allura? What're you doing here, of all places?",
  ui_story_31190601_158_dialog_content = "If you must know...",
  ui_story_31190601_159_dialog_content = "<color=#e8d9bb>Two days ago</color>",
  ui_story_31190601_160_dialog_content = "You need something, Gram? Or did you happen to find me a rare antique in Gannon City?",
  ui_story_31190601_161_dialog_content = "No, this is about Revy.",
  ui_story_31190601_162_dialog_content = "Revy? What happened?",
  ui_story_31190601_163_dialog_content = "Nothing! Well, not yet, anyway. I saw her leave early this morning, but she was dressed completely different than usual.",
  ui_story_31190601_164_dialog_content = "I followed her out the door, only to see her hitch a ride on a supply train heading for Umbraton. Would you mind keeping an eye on that kid for me?",
  ui_story_31190601_165_dialog_content = "Why not come here yourself? Aren't you curious to see what she's up to?",
  ui_story_31190601_166_dialog_content = "Since she didn't tell me herself, she didn't want me to know. I'm not the kind to do anything unnecessary.",
  ui_story_31190601_167_dialog_content = "She's free to do whatever she wants. All I care about is making sure she's safe.",
  ui_story_31190601_168_dialog_content = "Understood. I'll watch over her.",
  ui_story_31190601_169_dialog_content = "I spotted you in Umbraton right after I finished my conversation with Gram.",
  ui_story_31190601_170_dialog_content = "So why didn't you show up earlier?! I thought I was gonna be stuck here for a week!",
  ui_story_31190601_171_dialog_content = "For starters, when I saw you pestering that patrolman with a traffic sign... I honestly wanted to pretend I didn't even know you.",
  ui_story_31190601_172_dialog_content = "Also, I had much more pressing matters at the time. I would've missed a once-in-a-lifetime opportunity to see a one-of-a-kind antique had I decided to interfere in your little stunt.",
  ui_story_31190601_173_dialog_content = "Besides, given how petty your crime was, I figured they would only lock you up for a day or two with other equally-petty criminals.",
  ui_story_31190601_174_dialog_content = "That's a lot safer than letting you run amok in the streets of Umbraton, to be honest. No one in this jail stands a chance against you, after all.",
  ui_story_31190601_175_dialog_content = "(She thought that far... honestly, she's partially responsible for this situation...)",
  ui_story_31190601_176_dialog_content = "I never knew you could be so cold, Allura. It hurts!",
  ui_story_31190601_177_dialog_content = "Well, as a cold person, I guess I should just turn around and leave right now.",
  ui_story_31190601_178_dialog_content = "W-Wait, don't go! I was wrong, now could you please get me out of here? I'm dying to have some of Gram's food right now!",
  ui_story_31190601_179_dialog_content = "Well, I do miss his cooking too...",
  ui_story_31190601_180_dialog_content = "If I take you back to Gannon City, I could ask for a meal as payment for this little job of his.",
  ui_story_31190601_181_dialog_content = "Count me in!",
  ui_story_31190601_182_dialog_content = "We haven't sat down together for one of Gram's legendary meals in ages. This really brings back memories of the Dunefire Strike...",
  ui_story_31190601_183_dialog_content = "Today, I've gotta catch up on all the meals I've missed these last few days!",
  ui_story_31190601_184_dialog_content = "This meal could've been paired with some Super Blazing Hot Sauce...",
  ui_story_31190601_185_dialog_content = "Revy...",
  ui_story_31190601_186_dialog_content = "I won't give up so easily! Once I've eaten my fill, I'm going to keep chasing after the hot sauce of my dreams!",
  ui_story_31190601_187_dialog_content = "<color=#FFB400>Super Blazing Hot Sauce</color>... One day, you'll be mine!",
  ui_story_31190602_1_dialog_content = "This is a trial run, as well as a game of unrivaled joy.",
  ui_story_31190602_2_dialog_content = "Gronru, Tech Officer of the Illumina Federation, formally invites you to take part in this game.",
  ui_story_31190602_3_dialog_content = "It costs nothing to play, and there are no forms to fill out. All you need to do is hold my latest piece of cutting-edge technology, and you can even collect an advertising fee for your troubles.",
  ui_story_31190602_4_dialog_content = "With this device, you'll be able to protect the weak, as well as everyone in Illumina and even the world.",
  ui_story_31190602_5_dialog_content = "So what are you waiting for? Take action and join the Eclipsite Patrol now!",
  ui_story_31190602_6_dialog_content = "I'm glad you're here, Miss Revy.",
  ui_story_31190602_7_dialog_content = "I hope you don't mind me asking, but doesn't the letter strike you as suspicious?",
  ui_story_31190602_8_dialog_content = "It does! But if I can protect the weak like a real hero, I'm down to play this game.",
  ui_story_31190602_9_dialog_content = "Then you'll have to change into your new outfit for the commercial.",
  ui_story_31190602_10_dialog_content = "Huh? New outfit?",
  ui_story_31190602_11_dialog_content = "These clothes... They're <size=45>ridiculously heavy!</size>",
  ui_story_31190602_12_dialog_content = "It feels like I'm suffocating! How am I supposed to protect kids in this?!",
  ui_story_31190602_13_dialog_content = "So what role do you have in mind for me? You can tell me, right?",
  ui_story_31190602_14_dialog_content = "You'll know once Officer Gronru gets here!",
  ui_story_31190602_15_dialog_content = "Hey, PlayerName!",
  ui_story_31190602_16_dialog_content = "Revy? So you're the other performer, huh?",
  ui_story_31190602_17_dialog_content = "Those clothes look really cool on you!",
  ui_story_31190602_18_dialog_content = "Really? Because I feel like a turtle stuck in its shell.",
  ui_story_31190602_19_dialog_content = "Where's your new outfit?",
  ui_story_31190602_20_dialog_content = "Who knows? It all depends on Gronru, apparently.",
  ui_story_31190602_21_dialog_content = "Huh? Hey, check out that big cabinet over there! Is that where they're keeping the cameras and stuff?",
  ui_story_31190602_22_dialog_content = "Hold it! Keep your mitts off my S-Grade Experimental Materials!",
  ui_story_31190602_23_dialog_content = "Oh, thank goodness! If this got messed up, the whole commercial would be done for!",
  ui_story_31190602_24_dialog_content = "Ahem! It looks like everyone's present and accounted for!",
  ui_story_31190602_25_dialog_content = "Heheh, now I can finally unveil my latest invention! Try not to get too spooked!",
  ui_story_31190602_26_dialog_content = "Feast your eyes on the Eclipsite Vacuum Cleaner! Feel free to jump and shout now, if you want!",
  ui_story_31190602_27_dialog_content = "If it helps me kill Eclipsites and protect the weak, then that's good enough for me!",
  ui_story_31190602_28_dialog_content = "Wait, so your \"latest piece of cutting-edge technology\" is just a vacuum cleaner?!",
  ui_story_31190602_29_dialog_content = "Hey, you take that back right now! It's called the Eclipsite Vacuum Cleaner, thank you very much!",
  ui_story_31190602_30_dialog_content = "How could you be so ignorant?",
  ui_story_31190602_31_dialog_content = "Hey, it feels pretty good in my hands! How do I use it?",
  ui_story_31190602_32_dialog_content = "This one's been augmented to resemble your Alter-Blade. As for how to use it, I'll explain right before we start shooting.",
  ui_story_31190602_33_dialog_content = "You two should've figured it out by now, right? I want you to use the Eclipsite Vacuum Cleaner to help me shoot a promotional video!",
  ui_story_31190602_34_dialog_content = "And we're the only two actors?",
  ui_story_31190602_35_dialog_content = "Yep! My promo video doesn't need that many people.",
  ui_story_31190602_36_dialog_content = "(Actually, you're the only two people who showed up... Everyone else thought this was a prank.)",
  ui_story_31190602_37_dialog_content = "So, who's playing the main character?",
  ui_story_31190602_38_dialog_content = "That would be... Revy!",
  ui_story_31190602_39_dialog_content = "Then what about me?",
  ui_story_31190602_40_dialog_content = "You're gonna play the Eclipsite that ambushes Revy, only to get absolutely destroyed by her Eclipsite Vacuum Cleaner.",
  ui_story_31190602_41_dialog_content = "I object!",
  ui_story_31190602_42_dialog_content = "Overruled!",
  ui_story_31190602_43_dialog_content = "I just remembered something, Officer Gronru. Shouldn't we do Revy's makeup before we start filming?",
  ui_story_31190602_44_dialog_content = "Just leave that to me! Heeheehee, this is gonna be fun!",
  ui_story_31190602_45_dialog_content = "Urgh—This feels really weird.",
  ui_story_31190602_46_dialog_content = "Don't worry! This is top-of-the-line stuff, even though I have no clue what it is!",
  ui_story_31190602_47_dialog_content = "I think I should handle this, Officer Gronru.",
  ui_story_31190602_48_dialog_content = "Look, Revy's nostrils are packed with makeup now.",
  ui_story_31190602_49_dialog_content = "<size=45>Ahhh—Achoo—</size>",
  ui_story_31190602_50_dialog_content = "No way, this is too much fun! Just let me do it!",
  ui_story_31190602_51_dialog_content = "A little more here, a little more there, and presto!",
  ui_story_31190602_52_dialog_content = "It's perfect! Even I amaze myself sometimes!",
  ui_story_31190602_53_dialog_content = "Hmm, I think you should let Siobhan handle Revy's makeup this time.",
  ui_story_31190602_54_dialog_content = "<color=#e8d9bb>After a second makeover, the two actors rehearse their lines before learning how to use the vacuum cleaner.</color>",
  ui_story_31190602_55_dialog_content = "Three, two, one, action!",
  ui_story_31190602_56_dialog_content = "I wonder how well my new vacuum cleaner works?",
  ui_story_31190602_57_dialog_content = "Wow, it's so powerful. It feels like... An S-grade weapon in the very first level.",
  ui_story_31190602_58_dialog_content = "These lines are terrible. Are you sure this is okay?",
  ui_story_31190602_59_dialog_content = "It can't be helped. Officer Gronru wrote them herself.",
  ui_story_31190602_60_dialog_content = "It's time for your part!",
  ui_story_31190602_61_dialog_content = "<size=45>Hiss—</size>",
  ui_story_31190602_62_dialog_content = "An Eclipsite? Prepare to die!",
  ui_story_31190602_63_dialog_content = "Kneel before the awesome might of my Eclipsite Vacuum Cleaner!",
  ui_story_31190602_64_dialog_content = "(Ugh, I guess I should get into it a little more.)",
  ui_story_31190602_65_dialog_content = "(Huh? I'm not moving, so why... Why is my body starting to...)",
  ui_story_31190602_66_dialog_content = "Aaaahhhh—It's... It's gonna suck me in!",
  ui_story_31190602_67_dialog_content = "Time-out! Time-out! Gronru, cut!",
  ui_story_31190602_68_dialog_content = "My pants! My pants are getting sucked away!",
  ui_story_31190602_69_dialog_content = "Don't stop now! Keep going!",
  ui_story_31190602_70_dialog_content = "<color=#e8d9bb>The suction of the vacuum cleaner creates a powerful whirlwind inside the room.</color>",
  ui_story_31190602_71_dialog_content = "<color=#e8d9bb>It quickly begins to suck in everything in sight, including Gronru's cabinet of S-Grade Experimental Materials.</color>",
  ui_story_31190602_72_dialog_content = "Hiss—",
  ui_story_31190602_73_dialog_content = "Graaaaaaahh!!",
  ui_story_31190602_74_dialog_content = "What's an Eclipsite doing here?!",
  ui_story_31190602_75_dialog_content = "Keep filming! This is the most important part!",
  ui_story_31190602_76_dialog_content = "Are you serious?!",
  ui_story_31190602_77_option_content = "Direct Revy",
  ui_story_31190602_78_dialog_content = "Revy! Now's the time to put that Eclipsite Vacuum Cleaner to good use!",
  ui_story_31190602_79_dialog_content = "Make it feel the same pain and desperation that I just felt!",
  ui_story_31190602_80_option_content = "Hide behind Revy",
  ui_story_31190602_81_dialog_content = "That Eclipsite... It's coming right at us!",
  ui_story_31190602_82_dialog_content = "Ahhh—!",
  ui_story_31190602_83_dialog_content = "Drat! As much as I want to fight, I'll have to leave this to Revy.",
  ui_story_31190602_84_dialog_content = "The power supply's good, and so is the angle. Activating the Eclipsite Vacuum Cleaner!",
  ui_story_31190602_85_dialog_content = "I'll protect you, PlayerName!",
  ui_story_31190602_86_dialog_content = "???",
  ui_story_31190602_87_dialog_content = "Hiss—",
  ui_story_31190602_88_dialog_content = "Quit putting up such a fight, you stinkin' Eclipsite!",
  ui_story_31190602_89_dialog_content = "Revy! Lower the angle by fifteen degrees and go for its feet, so it loses balance!",
  ui_story_31190602_90_dialog_content = "You're history, Eclipsite!",
  ui_story_31190602_91_dialog_content = "Graaaaaah—",
  ui_story_31190602_92_dialog_content = "And so, our young hero protects the person most important to her.",
  ui_story_31190602_93_dialog_content = "Even a menacing Eclipsite is nothing but a speck of dust when faced with the Eclipsite Vacuum Cleaner's cleaning power.",
  ui_story_31190602_94_dialog_content = "Do you dream of becoming a hero in the eyes of other people? Do you wish to protect your loved ones and defeat Eclipsites with ease?",
  ui_story_31190602_95_dialog_content = "Then pick up the phone right now, call the Illumina Research Lab's hotline, and order your own today!",
  ui_story_31190602_96_dialog_content = "Eclipsite Vacuum Cleaner, no one can refuse it after using it.",
  ui_story_31190602_97_dialog_content = "Trust the Eclipsite Vacuum Cleaner to get the job done.",
  ui_story_31190602_98_dialog_content = "Please note: orders can only be placed between 3 PM and 4 PM, as Gronru is busy playing games the rest of the time.",
  ui_story_31190602_99_dialog_content = "Cut—!",
  ui_story_31190602_100_dialog_content = "That was perfect! I'd be dialing up the lab right now if I saw this!",
  ui_story_31190602_101_dialog_content = "Wouldn't you agree, Siobhan?",
  ui_story_31190602_102_dialog_content = "Um... Uh-huh!",
  ui_story_31190602_103_dialog_content = "Phew... I'm beaten.",
